"""Export reference data for src/engine/games.ts, generated by the Python implementation."""

import json
from pathlib import Path

from ffpr_common import games

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "test" / "fixtures" / "games.json"


def error_text(call) -> str:
    try:
        call()
    except games.UnknownGame as exc:
        return str(exc)
    raise AssertionError("expected UnknownGame")


out = {
    "games": [
        {
            "key": game.key,
            "app_id": game.app_id,
            "title": game.title,
            "achievement_count": game.achievement_count,
            "label": game.label,
        }
        for game in games.GAMES
    ],
    "total_achievements": games.TOTAL_ACHIEVEMENTS,
    "by_key": {key: games.by_key(key).key for key in ("ff1", "FF5", "fF6")},
    "by_app_id": {str(app_id): games.by_app_id(app_id).key for app_id in (1173770, 1173820)},
    "unknown_key": error_text(lambda: games.by_key("ff7")),
    "unknown_app_id": error_text(lambda: games.by_app_id(42)),
}

OUT.write_text(json.dumps(out, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
print(f"wrote {OUT}")
